//! The shim's logic, in a library so it can be tested.
//!
//! Lumina copies the shim executable into `<data-root>/bin/.shims/` once per
//! command (`php.exe`, `composer.exe`, `node.exe`, ...). Next to each copy is
//! a `<name>.shim` text file that Lumina rewrites whenever the active version
//! changes:
//!
//! ```text
//! # Generated by Lumina: PHP 8.4.26
//! C:\Lumina\bin\php\8.4.26\php.exe
//! -c
//! C:\Lumina\etc\php\8.4.26\php.ini
//! ```
//!
//! The first line that is not a comment is the program; every further line is
//! one argument placed before the user's own. So PATH points at one folder
//! forever, and `php -v` follows the version chosen in Lumina.

use std::ffi::OsStr;
use std::path::{Path, PathBuf};

/// Set for a program a shim falls back to, so two shim folders on PATH can
/// never hand a command back and forth.
pub const FALLBACK_ENV: &str = "LUMINA_SHIM_FALLBACK";

/// What a shim runs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Target {
    pub program: PathBuf,
    pub args: Vec<String>,
}

/// Parses a `.shim` file.
pub fn parse(text: &str) -> Option<Target> {
    let mut lines = text
        .lines()
        .map(|l| l.trim_end_matches('\r'))
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty());
    let program = PathBuf::from(lines.next()?.trim());
    Some(Target {
        program,
        args: lines.map(str::to_owned).collect(),
    })
}

/// Renders a `.shim` file.
pub fn render(comment: &str, target: &Target) -> String {
    let mut out = format!("# {comment}\n{}\n", target.program.display());
    for arg in &target.args {
        out.push_str(arg);
        out.push('\n');
    }
    out
}

/// `<shim exe without extension>.shim`.
pub fn shim_file(exe: &Path) -> PathBuf {
    exe.with_extension("shim")
}

/// The command name the shim was started as (`php` for `php.exe`).
pub fn command_name(exe: &Path) -> String {
    exe.file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "shim".into())
}

/// The next `name` on `path` (PATH) after Lumina's own shims: folders that
/// are `shim_dir` or hold a `<name>.shim` (another Lumina shim folder) are
/// skipped. On Windows `.exe`, `.cmd`, `.bat` and `.com` count.
pub fn find_on_path(name: &str, path: &OsStr, shim_dir: &Path) -> Option<PathBuf> {
    let extensions: &[&str] = if cfg!(windows) {
        &[".exe", ".cmd", ".bat", ".com"]
    } else {
        &[""]
    };
    std::env::split_paths(path)
        .filter(|dir| !dir.as_os_str().is_empty() && !same_dir(dir, shim_dir))
        .filter(|dir| !dir.join(format!("{name}.shim")).exists())
        .find_map(|dir| {
            extensions
                .iter()
                .map(|ext| dir.join(format!("{name}{ext}")))
                .find(|candidate| candidate.is_file())
        })
}

fn same_dir(a: &Path, b: &Path) -> bool {
    match (std::fs::canonicalize(a), std::fs::canonicalize(b)) {
        (Ok(a), Ok(b)) => a == b,
        _ => a == b,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        let target = Target {
            program: PathBuf::from(r"C:\Lumina\bin\php\8.4.26\php.exe"),
            args: vec!["-c".into(), r"C:\Lumina\etc\php\8.4.26\php.ini".into()],
        };
        let text = render("Generated by Lumina: PHP 8.4.26", &target);
        assert!(text.starts_with("# Generated by Lumina"));
        assert_eq!(parse(&text), Some(target.clone()));
        assert_eq!(parse(&text.replace('\n', "\r\n")), Some(target));
        assert_eq!(parse("# only a comment\n\n"), None);
    }

    #[test]
    fn names() {
        // Built for the OS the test runs on (a Windows path is one file name on Unix).
        let dir = Path::new("x").join(".shims");
        let exe = dir.join(format!("php{}", std::env::consts::EXE_SUFFIX));
        assert_eq!(command_name(&exe), "php");
        assert_eq!(
            shim_file(Path::new("/x/.shims/node")),
            PathBuf::from("/x/.shims/node.shim")
        );
    }

    #[test]
    fn falls_back_to_the_next_program_on_path() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let exe = format!("node{}", if cfg!(windows) { ".exe" } else { "" });
        let shims = tmp.path().join("shims");
        let other_shims = tmp.path().join("other-lumina");
        let real = tmp.path().join("nodejs");
        for dir in [&shims, &other_shims, &real] {
            std::fs::create_dir_all(dir).expect("mkdir");
            std::fs::write(dir.join(&exe), b"x").expect("exe");
        }
        std::fs::write(other_shims.join("node.shim"), b"").expect("shim");
        let path = std::env::join_paths([&shims, &other_shims, &tmp.path().join("missing"), &real])
            .expect("path");

        assert_eq!(find_on_path("node", &path, &shims), Some(real.join(&exe)));
        let only_shims = std::env::join_paths([&shims, &other_shims]).expect("path");
        assert_eq!(find_on_path("node", &only_shims, &shims), None);
    }
}
